// Build the Anthropic Messages API body from the incoming fields.
// Christopher Jackson's voice rules (no em dashes, period-split clauses,
// teacher-meets-CFO, no marketing fluff) are baked into the prompt.
//
// n8n's webhook v2 nests the parsed JSON body at items[0].json.body when
// Content-Type is application/json. Handle both nesting patterns so the
// code is robust to webhook config changes.
const item = items[0];
const json = item.json || {};
const input = json.body || json;

const SYSTEM = `You are writing a 2-sentence personal note to a high-school student about their dual-enrollment plan. The note appears on a free planner tool from FinLit Garden, run by Christopher Jackson. The voice must match Christopher's.

VOICE RULES (strict):
1. No em dashes. Use periods, commas, or colons.
2. Two sentences maximum. Short and direct.
3. Direct address. Use the student's first name once.
4. Teacher-meets-CFO tone: confident, data-driven, accessible. Lead with insight, not encouragement.
5. No marketing words like "amazing", "incredible", "exciting".
6. No financial advice. No promises about admissions outcomes.
7. Do not start with "Hi", "Hey", "Hello". Start with the student's name or an observation.
8. Do not invent courses, dates, GPAs, or numbers not provided.

OUTPUT ONLY THE NOTE. No preamble, no quotes, no markdown.`;

const userMessage = `Write the note for this student:

- Name: ${input.name}
- Grade: ${input.grade}
- Region: ${input.region}
- Major path: ${input.major}
- Target college destination: ${input.target}
- Recommended community college: ${input.college}`;

const makeBody = (model) => ({
  model,
  max_tokens: 200,
  system: SYSTEM,
  messages: [{ role: 'user', content: userMessage }]
});

return [{
  json: {
    haikuBody: makeBody('claude-haiku-4-5-20251001'),
    sonnetBody: makeBody('claude-sonnet-4-6'),
    _debug_input: input,
  }
}];

// Extract the paragraph text and validate length / shape.
// Validation is loose for narrative: any non-empty string of reasonable
// length (between 20 and 600 chars) is accepted.
const response = items[0].json;
const raw = response?.content?.[0]?.text ?? '';
const text = String(raw).trim();

const hasEmDash = text.includes('\u2014');
const lengthOk = text.length >= 20 && text.length <= 600;
const ok = lengthOk && !hasEmDash;

if (ok) {
  return [{ json: { valid: true, paragraph: text } }];
}
return [{ json: { valid: false, raw, reason: hasEmDash ? 'em_dash' : 'length_or_empty' } }];

// Same validation as Haiku step. If Sonnet also fails, return null
// so the API route returns paragraph: null and the client hides the block.
const response = items[0].json;
const raw = response?.content?.[0]?.text ?? '';
const text = String(raw).trim();
const hasEmDash = text.includes('\u2014');
const lengthOk = text.length >= 20 && text.length <= 600;
if (lengthOk && !hasEmDash) {
  return [{ json: { paragraph: text } }];
}
return [{ json: { paragraph: null } }];
